MAP=dict(foodmap.MAP); MAP.update(B14)
LOW=set(foodmap.LOW)|LOW14
NOENTRY=set(foodmap.NOENTRY)|{'소염진통제 (두통약)', '생수'}

def conv_date(s):
    m=re.match(r'(\d{2})/(\d{2})/(\d{2})', s.strip()); return f'20{m.group(1)}-{m.group(2)}-{m.group(3)}' if m else s.strip()
def meal_norm(slot):
    m=re.search(r'\(([^)]*)\)', slot); lb=m.group(1).strip() if m else ''
    if '섭취' in lb: return 'SKIP'
    for k in ['아침','점심','저녁','야식']:
        if k in lb: return k
    if '간식' in lb: return '오전간식' if slot.strip().startswith('오전') else '오후간식'
    return lb or '?'

df=pd.read_csv('input_raw.tsv', sep='\t', dtype=str).fillna('')
out=[]; nf=[]
for _,r in df.iterrows():
    food=r['음식명'].strip(); meal=r['시간대']
    if food=='' or food.lower()=='x' or '섭취' in meal: continue
    if food in NOENTRY:
        nf.append((r['ID'],conv_date(r['조회일']),food,'DB없음')); continue
    matched=MAP.get(food, food if food in DBSET else None)
    if matched is None or matched not in DBSET:
        nf.append((r['ID'],conv_date(r['조회일']),food,f'실패({matched})')); continue
    out.append({'ID':r['ID'],'성명':r['성명'],'조회일':conv_date(r['조회일']),'구분':r['구분'],
        '식사종류':meal_norm(meal),'원본음식':food,'매칭음식':matched,'식품번호':name2no[matched],
        '신뢰도':'LOW' if food in LOW else 'OK'})
od=pd.DataFrame(out); od.to_csv('mapped_rows.tsv', sep='\t', index=False)
print(f'입력대상 {len(out)} | 미입력/실패 {len(nf)} | 참가자 {od.ID.nunique()}')
print(f'--- 참가자별 행수 ---')
for uid,g in od.groupby("ID"): print(f'  {uid} {g.성명.iloc[0]}: {len(g)}행 ({g.조회일.min()}~{g.조회일.max()})')
fails=[x for x in nf if '실패' in x[3]]
noentry=[x for x in nf if 'DB없음' in x[3]]
print(f'--- 신규/매칭실패 {len(fails)}건 (고유 {len(set(x[2] for x in fails))}종) ---')
seen=set()
for x in fails:
    if x[2] not in seen: seen.add(x[2]); print(f'  {x[2]}')
print(f'--- NOENTRY(DB없음) {len(noentry)}건: {sorted(set(x[2] for x in noentry))} ---')
